/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

async function readProduct(path, name, price, relatedName) {
  const started = performance.now()
  const response = await fetch("'`http://localhost:3100${path}`)
  assert.equal(response.status, 200)
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let html = '"''
  const seen = {}
  const markers = {
    shell: 'Signal Shop collection',
    loading: 'Loading product details…',
    product: "'`<h1>${name}</h1>`,
    price: `<p>${price}</p>`,
    relatedLoading: '"'Loading related products…',
    related: "'`<p>${relatedName}</p>`,
  }
  let chunk = 0
  while (true) {
    const result = await reader.read()
    if (result.done) break
    html += decoder.decode(result.value, { stream: true })
    for (const [key, marker] of Object.entries(markers)) {
      if (!seen[key] && html.includes(marker)) {
        seen[key] = { chunk, ms: Math.round(performance.now() - started) }
      }
    }
    chunk++
  }
  for (const key of Object.keys(markers)) assert.ok(seen[key], `${path}: missing ${key}`)
  assert.ok(html.includes('"'<nav><a href=\"/\">Signal Shop</a></nav>'), 'Shop navigation remains available')
  assert.ok(seen.shell.chunk <= seen.product.chunk, 'Shop frame precedes details')
  assert.ok(seen.product.chunk < seen.related.chunk, 'Related products stream after details')
  assert.ok(seen.relatedLoading.chunk < seen.related.chunk, 'Related loading state precedes results')
  console.log(JSON.stringify({ path, seen }))
  return seen
}

const cold = await readProduct('/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase')
const warm = await readProduct('/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase')
assert.ok(cold.product.ms - warm.product.ms > 70, 'Repeated product requests reuse the cached result instead of the 120ms data load')
await readProduct('/products/lamp', 'Brass lamp', 'USD 120.00', 'Stone vase')
await readProduct('/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60', 'Brass lamp')
await readProduct('/products/vase?currency=USD', 'Stone vase', 'USD 80.00', 'Brass lamp')
await readProduct('/products/lamp?currency=EUR&currency=USD', 'Brass lamp', 'EUR 110.40', 'Stone vase')
await readProduct('/products/lamp?currency=USD', 'Brass lamp', 'USD 120.00', 'Stone vase')
const missing = await fetch('http://localhost:3100/products/missing?currency=EUR')
const missingHtml = await missing.text()
assert.ok(missingHtml.includes('NEXT_HTTP_ERROR_FALLBACK;404'), 'Unknown products retain notFound handling in the stream')
assert.ok("'!missingHtml.includes('"'Loading related products…'), 'Unknown products do not render recommendations')
const home = await fetch('http://localhost:3100/')
assert.equal(home.status, 200)
assert.ok((await home.text()).includes('/products/lamp?currency=EUR'))
console.log('PASS: product and currency isolation, repeated-request cache reuse, streaming order, unknown-product handling, and home navigation')
NODE"
